import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.BmD0ICqc.js";const d="/study/images/memory/address-translation.svg",f=JSON.parse('{"title":"仮想メモリ — アドレス変換・ページ・予約とコミット","description":"","frontmatter":{"title":"仮想メモリ — アドレス変換・ページ・予約とコミット","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"仮想アドレスが物理ページへ対応する仕組みと、Windowsの予約・コミット・常駐を区別する。TLB、ページフォルト、遅延割当、コピーオンライト、保護と観察方法を調べる。","aliases":["virtual memory","仮想メモリ","仮想アドレス","物理アドレス","アドレス空間","ページ","page table","ページ表","TLB","MMU","page fault","ページフォルト","ページフォールト","demand paging","demand-zero","copy-on-write","COW","reserve","commit","resident","working set","ワーキングセット","VirtualAlloc"],"verification":"Windows API契約とIntel SDMの一次資料照合（2026-11-02）"}},"headers":[],"relativePath":"os/virtual-memory.md","filePath":"os/virtual-memory.md"}'),n={name:"os/virtual-memory.md"};function i(s,e,c,l,m,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="仮想メモリ-—-アドレス変換・ページ・予約とコミット" tabindex="-1">仮想メモリ — アドレス変換・ページ・予約とコミット <a class="header-anchor" href="#仮想メモリ-—-アドレス変換・ページ・予約とコミット" aria-label="Permalink to &quot;仮想メモリ — アドレス変換・ページ・予約とコミット&quot;">​</a></h1><p>仮想メモリは、<strong>プロセスが使うアドレスを管理し、物理メモリとの対応とアクセス権を決める仕組み</strong>です。RAMが足りないときの退避だけでなく、プロセスの隔離、ファイルの共有、必要になってからの割当にも使います。</p><p>ここでは通常のWindowsアプリを中心に、CPU側はx64のページングを説明モデルにします。CPUの変換機構と、Windows APIの予約・コミットという契約を分けて読みます。GPUの仮想メモリ、仮想マシンの二段階変換、AWEやラージページの詳細は扱いません。</p><h2 id="仮想アドレスと物理アドレス" tabindex="-1">仮想アドレスと物理アドレス <a class="header-anchor" href="#仮想アドレスと物理アドレス" aria-label="Permalink to &quot;仮想アドレスと物理アドレス&quot;">​</a></h2><p>アプリがポインタでメモリを読むとき、そのアドレスは通常、そのプロセスの仮想アドレス空間に属します。変換後にメモリへアクセスするために使うのが物理アドレスです。ポインタの数値からRAM上の位置を直接読み取ることはできません。</p><p>プロセスAとBに同じ数値の仮想アドレスがあっても、同じデータとは限りません。OSが別の物理ページへ対応付けられるためです。同一プロセスのスレッドはアドレス空間を共有しますが、別プロセスとの共有には、共有メモリなどの仕組みを使います。隔離は「他プロセスのアドレスを整数として作れない」という意味ではなく、それだけでは対象のメモリへ到達できないという意味です。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/virtual-address-space" target="_blank" rel="noreferrer">Microsoft: Virtual Address Space</a></p><table tabindex="0"><thead><tr><th>言葉</th><th>このページでの意味</th></tr></thead><tbody><tr><td>仮想アドレス空間</td><td>プロセスが使うアドレスの範囲。すべての場所にデータがあるわけではない</td></tr><tr><td>仮想ページ</td><td>仮想アドレス空間を一定の大きさで区切った単位</td></tr><tr><td>物理ページ／ページフレーム</td><td>RAM側を区切った単位。仮想ページと対応付ける</td></tr><tr><td>マッピング</td><td>どの仮想ページを、どこへ、どの権限で対応させるかという関係</td></tr><tr><td>常駐（resident）</td><td>対象の内容が現在RAMにあること。アドレスの予約とは別の性質</td></tr></tbody></table><p><strong>仮想的に連続する領域を、物理的には離れたページで支えられます。</strong> 大きな配列の仮想アドレスが連続していても、同じ大きさの連続したRAM領域を丸ごと探す必要があるとは限りません。OSが対応を管理するので、アプリは通常、物理配置を意識せずに仮想アドレスを使います。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/virtual-address-space-and-physical-storage" target="_blank" rel="noreferrer">Microsoft: Virtual Address Space and Physical Storage</a></p><figure class="study-figure"><img src="'+d+'" alt="連続した仮想ページV0からV3を、離れたRAMの物理ページへ対応付ける模式図。CPUはTLBまたはページ表の情報から変換と権限を確認する。TLBミスはページフォルトと同義ではなく、ページフォルト時にはOSが対応を判断する。" width="760" height="1460"><figcaption><strong>同じアドレスを使い続けられることと、RAM上で連続していることは別。</strong> ページ番号と配置は説明用です。矢印は変換情報を参照する流れを示し、データのコピーを表しません。<a href="/study/images/memory/address-translation.svg" target="_blank" rel="noopener noreferrer">アドレス変換の図を拡大</a></figcaption></figure><h2 id="ページ・ページ表・tlbの仕事" tabindex="-1">ページ・ページ表・TLBの仕事 <a class="header-anchor" href="#ページ・ページ表・tlbの仕事" aria-label="Permalink to &quot;ページ・ページ表・TLBの仕事&quot;">​</a></h2><h3 id="ページ内の位置は引き継ぐ" tabindex="-1">ページ内の位置は引き継ぐ <a class="header-anchor" href="#ページ内の位置は引き継ぐ" aria-label="Permalink to &quot;ページ内の位置は引き継ぐ&quot;">​</a></h3><p>ページによる変換では、アドレスを「ページ番号」と「ページ内の位置（オフセット）」に分けます。例えばページサイズが4 KiBなら、仮想アドレス<code>0x12345080</code>は、仮想ページ番号<code>0x12345</code>とオフセット<code>0x080</code>に分かれます。対応する物理ページの先頭を見つけ、同じオフセットの場所へアクセスします。</p><p>4 KiBは基本ページの説明例です。Windowsでは<code>GetSystemInfo</code>が返す<code>SYSTEM_INFO.dwPageSize</code>で、通常のページサイズを確認します。<code>dwAllocationGranularity</code>は仮想領域の予約開始アドレスに関する粒度で、ページサイズとは別です。「64 bitなら全アドレスが使える」「ページも予約粒度もいつも同じ定数」とは扱いません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/sysinfoapi/ns-sysinfoapi-system_info" target="_blank" rel="noreferrer">Microsoft: SYSTEM_INFO</a></p><h3 id="ページ表は対応を記録し、tlbは変換を覚える" tabindex="-1">ページ表は対応を記録し、TLBは変換を覚える <a class="header-anchor" href="#ページ表は対応を記録し、tlbは変換を覚える" aria-label="Permalink to &quot;ページ表は対応を記録し、TLBは変換を覚える&quot;">​</a></h3><p>**ページ表（page table）**は、OSが管理する変換用データ構造です。x64の通常のページングでは、CPUのメモリ管理機構（MMU）が階層状の表をたどり、対応と権限を確認します。図ではこの階層を一つの箱に省略しています。</p><p>**TLB（Translation Lookaside Buffer）**は、アドレス変換の情報をキャッシュします。対象の情報があれば利用し、なければページ表などを参照して変換を進めます。ヒットした場合でもアクセス権を無視できるわけではありません。TLBは変換の情報、データキャッシュは読み書きする内容を扱う、と役割を分けます。</p><p><strong>TLBミスだけで、ページフォルトやディスク読込みになるわけではありません。</strong> x64では有効な変換をハードウェアが求められる場合、OSの例外処理へ渡さずアクセスを進められます。表の形式や段数、キャッシュ構成は対象CPU・設定に依存します。<a href="https://cdrdv2.intel.com/v1/dl/getContent/671190#page=153" target="_blank" rel="noreferrer">Intel SDM Volume 3A, §5.10「Caching Translation Information」</a></p><h2 id="windowsの予約・コミット・常駐を分ける" tabindex="-1">Windowsの予約・コミット・常駐を分ける <a class="header-anchor" href="#windowsの予約・コミット・常駐を分ける" aria-label="Permalink to &quot;Windowsの予約・コミット・常駐を分ける&quot;">​</a></h2><p>以下は、通常の<code>VirtualAlloc</code>によるプライベートメモリの説明です。ファイルマッピングなど、別のAPIで作る領域まで同じ手順になるとは限りません。</p><p>ファイルの内容を仮想アドレス空間へ対応付ける方式は、<a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a>で扱います。ビューを作ることと、全内容がRAMへ読み込まれていることは別です。必要なページへのアクセスで、ページの準備やI/Oを待つ場合もあります。これは<code>ReadAsync</code>などの非同期readを発行したこととも異なります。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/file-mapping" target="_blank" rel="noreferrer">Microsoft: File Mapping</a></p><table tabindex="0"><thead><tr><th>言葉</th><th>何を確保・確認するか</th><th>その時点でRAMを占有するか</th></tr></thead><tbody><tr><td>予約（reserve）</td><td>そのプロセスで使う仮想アドレスの範囲を取り置く</td><td>対象データの物理ページは割り当てない</td></tr><tr><td>コミット（commit）</td><td>ページを使用するための、システムの資源負担を引き受けさせる</td><td>それだけで全ページがRAMに置かれるとは限らない</td></tr><tr><td>常駐（resident）</td><td>現在、内容がRAMにあるかを表す</td><td>現在の配置についての状態</td></tr></tbody></table><p>Windowsのページ状態には、空きの<code>MEM_FREE</code>、予約済みの<code>MEM_RESERVE</code>、コミット済みの<code>MEM_COMMIT</code>があります。<strong>residentは、この三つに続く第四のページ状態ではありません。</strong> コミット済みでも、まだ触っていない、あるいは常駐していない場合があります。アクセスできるかには保護属性も関係します。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/page-state" target="_blank" rel="noreferrer">Microsoft: Page State</a></p><p><code>MEM_RESERVE</code>はアドレスの場所取りです。予約しただけのページを読んだり書いたりすることはできません。<code>MEM_COMMIT</code>はコミット量（commit charge）に関係する処理で、<strong>呼出し時に全ページへ物理RAMを配る処理ではありません</strong>。通常のこの割当では、初回の読取り・書込みで必要な物理ページが用意され、初期内容はゼロになります。<code>malloc</code>から再利用された領域までゼロになるという意味ではありません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-virtualalloc" target="_blank" rel="noreferrer">Microsoft: VirtualAlloc — MEM_RESERVE / MEM_COMMIT</a></p><h3 id="「仮想メモリ」と「ページファイル」は同義ではない" tabindex="-1">「仮想メモリ」と「ページファイル」は同義ではない <a class="header-anchor" href="#「仮想メモリ」と「ページファイル」は同義ではない" aria-label="Permalink to &quot;「仮想メモリ」と「ページファイル」は同義ではない&quot;">​</a></h3><p>ページファイルは、変更されたページの内容を退避し、システムのコミット可能量を支えるために使われます。仮想アドレスの変換・保護・共有という仕組み全体の名前ではありません。コミット量も、今ページファイルへ書かれているデータ量とは一致しません。</p><p>ページファイルがなくても、RAMに裏付けられる範囲で仮想メモリを使用できます。ただしコミット上限やクラッシュダンプ等の条件が変わります。ここから「無効にすべき」と設定方針を導くのではなく、予約量・コミット量・RAMの使用量・退避先を区別します。<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-client/performance/introduction-to-the-page-file" target="_blank" rel="noreferrer">Microsoft: Introduction to page files</a></p><h2 id="ページフォルトで起きること" tabindex="-1">ページフォルトで起きること <a class="header-anchor" href="#ページフォルトで起きること" aria-label="Permalink to &quot;ページフォルトで起きること&quot;">​</a></h2><p>ページフォルトは、アクセスに必要な変換がそのまま使えない場合や、ページの権限に合わないアクセスなどで、CPUから処理を移す仕組みです。OSは原因と領域の管理情報を調べ、処理を続けられるか判断します。x64の例外には、単に変換先がない場合と保護違反の場合を区別する情報があります。<a href="https://cdrdv2.intel.com/v1/dl/getContent/671190#page=148" target="_blank" rel="noreferrer">Intel SDM Volume 3A, §5.7「Page-Fault Exceptions」</a></p><table tabindex="0"><thead><tr><th>きっかけ</th><th>OSが行うことの例</th><th>毎回ディスクI/Oが必要か</th></tr></thead><tbody><tr><td>コミットした通常ページへの初回アクセス</td><td>ゼロ初期化されたページを用意する（demand-zero）</td><td>不要な場合がある</td></tr><tr><td>内容が既にRAMにあるが、現在のワーキングセットにない</td><td>既存のページを再び利用可能にする</td><td>不要な場合がある</td></tr><tr><td>内容を退避先やマッピング元から読み戻す必要がある</td><td>ページファイルやファイルから読み込む</td><td>読込みを必要とする</td></tr><tr><td>予約だけの領域、解放済み領域、許可されない書込み</td><td>正常な割当の続きとしては扱わず、例外を通知する</td><td>読み込めば解決するとは限らない</td></tr></tbody></table><p>Windowsでは、退避先へのアクセスなしに解決できるものをsoft fault、退避先から読込みが必要なものをhard faultと区別します。<strong>fault数が増えたことだけでは、ディスクが遅かったとも、メモリバグとも判断できません。</strong> 初回アクセスも起きるため、原因やI/O、処理時間を合わせて観察します。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/working-set" target="_blank" rel="noreferrer">Microsoft: Working Set</a></p><p>必要になってからページの内容を用意する考え方が<strong>demand paging</strong>です。起動時に全データをRAMへ展開せず、アクセスに応じて準備することができます。一方、処理の途中で準備やI/Oを待つ可能性もあります。ゲームのヒッチを調べるときは、確保APIの呼出し時間だけでなく、その領域を初めて触った区間も分けて観察します。</p><p>重要なのは、<strong>未コミットへのアクセスは、コミット済みの正常な初回アクセスとは違う</strong>ことです。普通のアプリが予約領域を触るだけで、自動的にコミットされる契約ではありません。必要な範囲を先にコミットしてから使います。不正アクセスはAccess Violationとして通知され得ます。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/page-state" target="_blank" rel="noreferrer">Microsoft: Page State</a></p><h2 id="コピーオンライトと共有" tabindex="-1">コピーオンライトと共有 <a class="header-anchor" href="#コピーオンライトと共有" aria-label="Permalink to &quot;コピーオンライトと共有&quot;">​</a></h2><p>複数の仮想ページを同じ物理ページへ対応付けることもできます。**コピーオンライト（copy-on-write、COW）**は、変更するまで内容を共有し、書込み時に必要なページを複製して、その側の対応を変更する方式です。最初から各利用者へ全ページを複製するより、コピーと物理メモリの消費を遅らせられます。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/memory-protection" target="_blank" rel="noreferrer">Microsoft: Memory Protection — Copy-on-Write Protection</a></p><p>Windowsの具体例は、<code>MapViewOfFile</code>の<code>FILE_MAP_COPY</code>で作るビューです。書き込んだページはそのプロセス用のコピーになり、元ファイルへは書き戻されません。通常の書込み可能な共有ビューとは契約が異なります。「共有されているページなら、必ず書込み時にコピーされる」とは考えません。</p><p>また、<strong>実際のコピーを遅らせることと、コミット量の計上を遅らせることも別</strong>です。<code>FILE_MAP_COPY</code>では全ページが書き換えられ得るため、ビュー全体についてコミット量が計上されます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-mapviewoffile" target="_blank" rel="noreferrer">Microsoft: MapViewOfFile — FILE_MAP_COPY</a></p><p><a href="/study/practice/io/mapped-file-observation.html">ファイルマッピングの観察例</a>では、ファイルに対応するビューと、その範囲・寿命を確かめます。マッピング元のファイル、マッピングオブジェクト、ビューは別の資源です。ビューを解除した後は、そのアドレスやそこを借りた参照を使いません。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/closing-a-file-mapping-object" target="_blank" rel="noreferrer">Microsoft: Closing a File Mapping Object</a></p><h2 id="保護が防ぐもの・防がないもの" tabindex="-1">保護が防ぐもの・防がないもの <a class="header-anchor" href="#保護が防ぐもの・防がないもの" aria-label="Permalink to &quot;保護が防ぐもの・防がないもの&quot;">​</a></h2><p>Windowsでは、<code>PAGE_READONLY</code>、<code>PAGE_READWRITE</code>、<code>PAGE_NOACCESS</code>、<code>PAGE_EXECUTE_READ</code>などでページへの操作を指定します。読めること・書けること・命令として実行できることは別です。保護はページ単位なので、ページ内の一部分だけへ同じ仕組みで異なる保護を付けることはできません。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/memory-protection-constants" target="_blank" rel="noreferrer">Microsoft: Memory Protection Constants</a></p><p>そのため、OSの保護だけでC++のオブジェクト寿命や配列の範囲を検査できるわけではありません。解放済みの領域がまだアクセス可能なページに残っていたり、はみ出した先も書込み可能だったりすると、すぐには例外にならない場合があります。<strong>「クラッシュしなかった」は正しいアクセスの証明になりません。</strong> 言語側の規則と<a href="/study/runtime/memory/memory-bugs.html">メモリバグの検出</a>も必要です。</p><h2 id="解放と観察のつなぎ方" tabindex="-1">解放と観察のつなぎ方 <a class="header-anchor" href="#解放と観察のつなぎ方" aria-label="Permalink to &quot;解放と観察のつなぎ方&quot;">​</a></h2><p><code>VirtualFree</code>の<code>MEM_DECOMMIT</code>は、コミットを解除して予約状態へ戻します。<code>MEM_RELEASE</code>は通常、予約した領域全体を解放してアドレスの取り置きも終えます。後者は予約時のベースアドレスとサイズ<code>0</code>を渡すなど、API固有の条件があります。どちらもC++のデストラクタを呼ぶ操作ではありません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-virtualfree" target="_blank" rel="noreferrer">Microsoft: VirtualFree</a></p><p>通常の<code>free</code>や<code>delete</code>はアロケータ側へ返す操作も含むため、毎回このOS APIの解放まで進むとは限りません。その経路は<a href="/study/runtime/memory/allocation-journey.html">確保すると内部で何が起きるか</a>、再利用戦略は<a href="/study/runtime/memory/allocators-and-pools.html">プール・アリーナ</a>へ進んで確認できます。</p><p>観察するときは、質問と指標を合わせます。</p><table tabindex="0"><thead><tr><th>知りたいこと</th><th>Windowsで見るもの</th></tr></thead><tbody><tr><td>この仮想領域は予約済みか、コミット済みか</td><td><code>VirtualQuery</code>の<code>State</code></td></tr><tr><td>読み書きなどの保護は何か</td><td><code>VirtualQuery</code>の<code>Protect</code></td></tr><tr><td>対象ページの常駐などの情報</td><td><code>QueryWorkingSetEx</code></td></tr><tr><td>現在のプロセスでRAMに常駐するページ量</td><td>ワーキングセット。共有ページも含み得る</td></tr></tbody></table><p><code>VirtualQuery</code>は仮想領域の状態や保護を調べるAPIです。<code>MEM_COMMIT</code>という結果だけで全ページの常駐を確認したことにはなりません。ページごとの情報には、対象アドレスを指定する<code>QueryWorkingSetEx</code>などを使います。<a href="https://learn.microsoft.com/en-us/windows/win32/api/memoryapi/nf-memoryapi-virtualquery" target="_blank" rel="noreferrer">Microsoft: VirtualQuery</a>、<a href="https://learn.microsoft.com/en-us/windows/win32/api/psapi/nf-psapi-queryworkingsetex" target="_blank" rel="noreferrer">QueryWorkingSetEx</a></p><p><a href="/study/practice/memory/windows-memory-observation.html">Windowsメモリ観察サンプル</a>では、予約・コミット・ページへの書込み・コミット解除・解放を分けて試せます。測定値は、その瞬間のOSの管理やプロセス全体の活動にも左右されます。「要求したバイト数と、ある指標の増分が毎回ぴったり一致する」と決めず、何を数えている値かを先に確認してください。</p>',47)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
